"""Shared helpers for discogs-tag and album-m3u.

A launcher adds its own resolved directory to sys.path before importing
this module, so a symlink to the launcher still finds it.

Playlist rules
--------------
album-m3u writes one playlist per album, named after the album folder,
with this header::

    #EXTM3U
    # generated by album-m3u

Only playlists that carry that marker, or legacy playlists written by older
versions of album-m3u (see is_legacy_generated), are ever replaced or
deleted. Every other .m3u/.m3u8 file is treated as hand-made and left alone.
"""

from __future__ import annotations

__version__ = "0.1.0"

import os
import re
from pathlib import Path

AUDIO_EXTS = {
    ".flac",
    ".mp3",
    ".m4a",
    ".aac",
    ".ogg",
    ".opus",
    ".wav",
    ".wma",
    ".ape",
    ".wv",
    ".aiff",
    ".aif",
    ".alac",
}

PLAYLIST_EXTS = {".m3u", ".m3u8"}
PLAYLIST_SUFFIX = ".m3u"
GENERATED_MARKER = "# generated by album-m3u"

DISC_DIR = re.compile(r"^(?:cd|disc|disk)\s*[-_. ]?\s*\d+", re.I)


def natural_key(name: str) -> list:
    """Sort 2 before 10, case-insensitive."""
    return [int(p) if p.isdigit() else p.casefold() for p in re.split(r"(\d+)", name)]


def is_audio(path: Path) -> bool:
    return path.is_file() and path.suffix.lower() in AUDIO_EXTS


def is_playlist(path: Path) -> bool:
    return path.is_file() and path.suffix.lower() in PLAYLIST_EXTS


def audio_in(folder: Path) -> list[Path]:
    """Audio files sitting directly in folder, in natural order."""
    tracks: list[Path] = []
    try:
        for entry in folder.iterdir():
            if is_audio(entry):
                tracks.append(entry)
    except OSError:
        return []
    tracks.sort(key=lambda p: natural_key(p.name))
    return tracks


def disc_dirs_with_audio(folder: Path) -> list[Path]:
    """CD1/Disc 2/... subfolders of folder that contain audio, in order."""
    found: list[Path] = []
    try:
        entries = list(folder.iterdir())
    except OSError:
        return []
    for entry in entries:
        if entry.is_dir() and not entry.is_symlink() and DISC_DIR.match(entry.name) and audio_in(entry):
            found.append(entry)
    found.sort(key=lambda p: natural_key(p.name))
    return found


def album_playlist_tracks(album_dir: Path) -> list[Path]:
    """Tracks an album playlist should list.

    Audio directly in the folder, or, for a multi-disc album whose folder
    holds only CD1/CD2/... subfolders, every disc's audio in disc order.
    """
    here = audio_in(album_dir)
    if here:
        return here
    tracks: list[Path] = []
    for disc in disc_dirs_with_audio(album_dir):
        tracks.extend(audio_in(disc))
    return tracks


def playlist_path(album_dir: Path) -> Path:
    return album_dir / f"{album_dir.name}{PLAYLIST_SUFFIX}"


def _entry_for(album_dir: Path, track: Path) -> str:
    rel = track.relative_to(album_dir).as_posix()
    # A line starting with "#" is a comment in M3U; "./" keeps it a path.
    if rel.startswith("#"):
        rel = "./" + rel
    return rel


def render_playlist(album_dir: Path, tracks: list[Path]) -> list[str]:
    """Playlist lines (without newlines) for tracks, relative to album_dir."""
    lines = ["#EXTM3U", GENERATED_MARKER]
    for track in tracks:
        entry = _entry_for(album_dir, track)
        if "\n" in entry or "\r" in entry:
            continue  # cannot be represented in M3U; skipped (callers warn)
        lines.append(entry)
    return lines


def unrepresentable(album_dir: Path, tracks: list[Path]) -> list[Path]:
    return [t for t in tracks if "\n" in t.name or "\r" in t.name]


def encode_lines(lines: list[str]) -> bytes:
    """UTF-8, keeping undecodable Linux filename bytes exactly as on disk."""
    return ("\n".join(lines) + "\n").encode("utf-8", "surrogateescape")


def read_lines(path: Path) -> list[str] | None:
    try:
        raw = path.read_bytes()
    except OSError:
        return None
    if raw.startswith(b"\xef\xbb\xbf"):
        raw = raw[3:]
    text = raw.decode("utf-8", "surrogateescape")
    return [line.rstrip("\r") for line in text.split("\n")]


def is_marked_generated(path: Path) -> bool:
    """True when the playlist carries the album-m3u marker in its header."""
    lines = read_lines(path)
    if not lines:
        return False
    head = [line.strip() for line in lines[:5]]
    return any(line.startswith(GENERATED_MARKER) for line in head)


def is_legacy_generated(path: Path) -> bool:
    """A playlist written by album-m3u before it added a header.

    Old versions wrote ``<folder name>.m3u`` holding bare file names of the
    folder's audio files in natural order, one per line, with no comments.
    A file only counts as one of those when all of that still holds: same
    name as its folder, no '#' lines, no paths, every entry an existing
    audio file in that folder, natural order, no duplicates. Anything else
    (reordered, subsets with paths, comments, missing files) is hand-made.
    """
    folder = path.parent
    if path.suffix.lower() != ".m3u" or path.stem != folder.name:
        return False
    lines = read_lines(path)
    if lines is None:
        return False
    entries = [line.strip() for line in lines if line.strip()]
    if not entries:
        return False
    for entry in entries:
        if entry.startswith("#") or "/" in entry or "\\" in entry:
            return False
        if Path(entry).suffix.lower() not in AUDIO_EXTS:
            return False
        if not (folder / entry).is_file():
            return False
    if len(set(entries)) != len(entries):
        return False
    if entries != sorted(entries, key=natural_key):
        return False
    return True


def is_generated_playlist(path: Path) -> bool:
    return is_marked_generated(path) or is_legacy_generated(path)


def looks_like_stale_legacy(path: Path) -> bool:
    """Bare audio file names only, but some listed files no longer exist.

    These are probably old generated playlists that were carried along by
    a rename. They are reported, never deleted automatically.
    """
    if is_generated_playlist(path):
        return False
    lines = read_lines(path)
    if not lines:
        return False
    entries = [line.strip() for line in lines if line.strip()]
    if not entries:
        return False
    for entry in entries:
        if entry.startswith("#") or "/" in entry or "\\" in entry:
            return False
        if Path(entry).suffix.lower() not in AUDIO_EXTS:
            return False
    return any(not (path.parent / entry).exists() for entry in entries)


def playlists_in(folder: Path) -> list[Path]:
    try:
        found = [p for p in folder.iterdir() if is_playlist(p)]
    except OSError:
        return []
    found.sort(key=lambda p: natural_key(p.name))
    return found


def generated_playlists_for_album(album_dir: Path) -> list[Path]:
    """Generated playlists in the album folder and its disc subfolders."""
    found = [p for p in playlists_in(album_dir) if is_generated_playlist(p)]
    for disc in disc_dirs_with_audio(album_dir):
        found.extend(p for p in playlists_in(disc) if is_generated_playlist(p))
    return found


def playlist_is_current(path: Path, album_dir: Path, tracks: list[Path]) -> bool:
    """True when path already holds exactly what we would write."""
    lines = read_lines(path)
    if lines is None:
        return False
    while lines and lines[-1] == "":
        lines.pop()
    return lines == render_playlist(album_dir, tracks)


def write_playlist_file(dest: Path, lines: list[str]) -> None:
    """Write via a temp file and rename, so a crash never leaves half a file."""
    tmp = dest.with_name(f".{dest.name}.tmp-{os.getpid()}")
    try:
        with open(tmp, "wb") as handle:
            handle.write(encode_lines(lines))
        os.replace(tmp, dest)
    finally:
        if tmp.exists():
            tmp.unlink()
